                # Check all 8-direction neighbors for 8s
                has_neighbor = False
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and new_grid[nr][nc] == 8:
                            has_neighbor = True
                            break
                    if has_neighbor:
                        break

                # If completely isolated (no 8 neighbors), change to 0
                if not has_neighbor:
